class Solution {
  public int makeStringGood(String s) {
    int n = s.length();
    int[] c = new int[26];
    for (int i = 0; i < n; i++) c[s.charAt(i) - 'a']++;
    int best = Integer.MAX_VALUE;
    for (int t = 1; t <= n; t++) best = Math.min(best, solve(c, t));
    return best;
  }

  private static int solve(int[] c, int t) {
    int[] dp = new int[28];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE / 2);
    dp[0] = 0;
    for (int i = 0; i < 26; i++) {
      dp[i + 1] = Math.min(dp[i + 1], dp[i] + Math.min(c[i], Math.abs(c[i] - t)));
      if (i + 1 < 26) dp[i + 2] = Math.min(dp[i + 2], dp[i] + pair(c[i], c[i + 1], t));
    }
    return dp[26];
  }

  private static int pair(int a, int b, int t) {
    int best = Integer.MAX_VALUE;
    for (int ti = 0; ti <= t; ti += t) {
      for (int tj = 0; tj <= t; tj += t) {
        int cost, nb = b;
        if (a > ti) {
          int e = a - ti;
          cost = e;
          nb += Math.min(e, Math.max(0, tj - b));
        } else {
          cost = ti - a;
        }
        cost += Math.abs(nb - tj);
        best = Math.min(best, cost);
      }
    }
    return best;
  }
}
